/* Teaching visuals are authored diagrams, never presented as real screenshots. */
function teachingBoxes(items){return `<div class="teaching-flow">${items.map(([label,text])=>`<div><b>${esc(label)}</b><span>${esc(text)}</span></div>`).join('')}</div>`;}
function beginnerDiagram(kind){const diagrams={
 computer:()=>teachingBoxes([['你 / 浏览器','输入地址、看页面'],['网络','传递请求与响应'],['服务器','处理请求、返回结果']]),
 terminal:()=>`<div class="terminal-sample"><div class="sample-title">终端窗口样式示意 · 不是实际电脑截图</div><pre><span class="sample-prompt">student@lab:~$</span> <span class="sample-command">pwd</span>\n<span class="sample-output">/home/student</span>\n<span class="sample-prompt">student@lab:~$</span> <span class="sample-cursor">▌</span></pre></div><ol class="picture-key"><li><b>提示符 student@lab:~$</b>：用户、机器、当前位置和等待标记；通常由终端显示。</li><li><b>输入 pwd</b>：你输入的命令，按回车执行。不要带上 $。</li><li><b>输出 /home/student</b>：程序返回的当前位置。</li><li><b>最后一行</b>：等待下一条命令；光标是输入位置。</li></ol>`,
 directory:()=>`<div class="directory-example"><pre>/                          ← 根目录，整棵树的起点\n├── home/                  ← 用户目录通常在这里\n│   └── student/           ← 当前所在的家目录\n│       ├── notes.txt      ← 文件\n│       └── practice/      ← 子目录\n├── etc/                   ← 常见系统配置目录\n└── var/\n    └── log/               ← 常见日志目录</pre><p>本课目录树是示例。实际服务的日志也可能在其他目录、容器输出或系统日志中。</p></div>`+teachingBoxes([['pwd','显示我在哪里'],['ls','列出这里有什么'],['cd practice','进入下一级 practice'],['cd ..','回到上一级']]),
 'network-device':()=>teachingBoxes([['电脑 / 手机','终端：使用网络的设备'],['网卡','有线或无线的网络接口'],['网线 / Wi-Fi','连接方式'],['交换机 / AP','接入本地网络']]),
 addresses:()=>`<div class="address-compare"><div><small>MAC · 当前链路接口地址</small><code>02:1A:2B:3C:4D:5E</code><p>六组 · 常用冒号分隔 · 0–9、A–F</p></div><div><small>IPv4 · 网络逻辑地址</small><code>192.168.10.20</code><p>四组 · 点分隔 · 每组 0–255</p></div></div><p>这两种地址通常同时存在。MAC 不是永远不变的身份证；IP 也不直接等于某个人。</p>`,
 'switch-board':()=>`<div class="switch-sample"><h3>交换机面板样式示意</h3><div class="switch-ports">${['1 → 电脑 A','2 → 电脑 B','3 → 打印机','4 → 上联'].map(x=>`<div><span>▣</span><b>${x}</b></div>`).join('')}</div><p>这些是插网线的物理端口。指示灯常提示连接或活动；具体含义以设备手册为准。</p></div>`+teachingBoxes([['学习来源','MAC A 来自端口 1'],['查找目标','MAC B 已在端口 2'],['转发数据','往端口 2 发送']]),
 'gateway-map':()=>teachingBoxes([['电脑','192.168.10.20/24'],['交换机','连接本地设备'],['路由器本地接口','192.168.10.1 · 默认网关'],['其他网络','经路由选择下一跳']]),
 'dns-map':()=>teachingBoxes([['名字','example.com'],['DNS 查询','问这个名字对应什么地址'],['示例查询结果','192.0.2.10 · 文档地址'],['另一步：请求网站','连接服务、等待响应']]),
 'request-map':()=>teachingBoxes([['接入网络','终端、网卡、交换机 / AP'],['地址配置','IP、掩码、网关、DNS'],['名字查询','DNS 找到目标地址'],['发出请求','经网络到达服务'],['观察响应','页面或错误，再查证据']])
 };return diagrams[kind]?`<figure class="teaching-picture"><figcaption>看图认识 · 教学示意</figcaption>${diagrams[kind]()}</figure>`:'';}
const beginnerBaseDiagram=simpleDiagram;
simpleDiagram=function(kind){return beginnerDiagram(kind)||beginnerBaseDiagram(kind);};
function glossaryHTML(words=Object.keys(beginnerTerms)){return `<section id="beginner-glossary" class="section glossary"><h2>不认识的词，点开看</h2><p>先看白话解释，再回到当前句子；不用一次背完。终端和端口都有两种常见含义。</p>${words.map(w=>`<details><summary>${esc(w)}</summary><p>${esc(beginnerTerms[w])}</p></details>`).join('')}</section>`;}
function relevantTerms(text){return Object.keys(beginnerTerms).filter(w=>text.includes(w));}
const beginnerBaseCourse=hubCourseHTML,beginnerBaseClassroom=classroom,beginnerBaseHome=hubHome,beginnerBaseGuide=learningGuideHTML,beginnerBaseRender=render,beginnerBaseNav=hubNav;
hubCourseHTML=function(){let html=beginnerBaseCourse();if(hubPhase!=='learn')return html;const c=activeHubLesson();const terms=c.beginner?relevantTerms(c.body.join(' ')+c.examples.map(e=>e.text).join(' ')+c.related):relevantTerms(c.body.join(' ')+c.related);html=html.replace('<h2>标准用法与例子</h2>',glossaryHTML(terms)+'<h2>跟着例子读一遍</h2>');if(c.beginner)html=html.replace('从场景理解，再看标准用法','这一课只认识一个主题').replace('<img src="assets/learning-journey.webp" alt="学习阶梯插画">','').replace('<h2>关联知识</h2>','<h2>这一课记住什么？</h2>');return html;};
classroom=function(){let html=beginnerBaseClassroom();if(learningTab!=='learn')return html;const c=current();const words=relevantTerms(JSON.stringify(c));const panel=(c.id===0?beginnerDiagram('terminal'):c.id===1?beginnerDiagram('directory'):'')+glossaryHTML(words);return html.replace('<div class="meta">',panel+'<div class="meta">');};
hubHome=function(){let html=beginnerBaseHome();html=html.replace('第一次来，从 Linux 第 1 课开始。','第一次来，先学零基础准备课：认识电脑、终端窗口、目录和网络设备，再进入 Linux。');html=html.replace(/<button class="primary" data-action="lesson" data-id="\d+">[\s\S]*?<\/button>/,`<button class="primary" data-hub="lesson" data-track="beginner" data-index="${hubNextIndex('beginner')}">${hubState.completed.beginner.length?'继续零基础准备课':'我是新手：从看图认识开始'}</button><button class="secondary" data-action="lesson" data-id="${firstUnfinishedCourse()}">已认识基础概念？进入 Linux</button>`);html=html.replace('基础路线已通过',`零基础准备已通过 ${hubState.completed.beginner.length}/${hubCurriculum.beginner.length} 课 · Linux 基础路线已通过`);html=html.replace('<div class="concept-flow">','<p><b>推荐起点：零基础准备 → Linux 文件与命令 → 日志与管道 → 网络配置 → 数据库与部署。</b>网络课堂也从设备名称开始，暂时不用直接学路由协议。</p><div class="concept-flow">');return html;};
learningGuideHTML=function(){return beginnerBaseGuide().replace('选基础第 1 课。','选零基础准备第 1 课。').replace('还不会命令就从 Linux 起步','不懂术语先看图认识电脑、终端和网络；认识后再从 Linux 起步').replace('<h2>第一次的五个动作</h2>','<div class="hero-actions"><button class="primary" data-hub="lesson" data-track="beginner" data-index="0">从零基础第 1 课开始</button><button class="secondary" data-beginner="glossary">查看图解词典</button></div><h2>第一次的五个动作</h2>');};
hubNav=function(){return beginnerBaseNav().replace('</nav>',`<button data-beginner="glossary" ${view==='glossary'?'aria-current="page"':''}>图解词典</button></nav>`);};
render=function(){if(view==='glossary'){$('app').innerHTML=hubNav()+`<main class="hub-main"><div class="page-head"><div><div class="eyebrow">遇到生词，随时回来</div><h1>术语不是起点，理解才是。</h1><p>先分清界面和设备，再看术语如何一起工作。所有图均为教学示意。</p></div><button class="primary" data-hub="subject" data-id="beginner">查看零基础路线</button></div><label for="term-search">搜索术语或解释，例如 MAC、网关、文件夹</label><input id="term-search" type="search" placeholder="输入一个不认识的词"><div id="term-results">${glossaryHTML()}</div>${beginnerDiagram('terminal')}${beginnerDiagram('directory')}${beginnerDiagram('switch-board')}${beginnerDiagram('gateway-map')}${beginnerDiagram('dns-map')}</main>`;return;}return beginnerBaseRender();};
document.addEventListener('click',e=>{if(e.target.closest('[data-beginner="glossary"]')){view='glossary';render();window.scrollTo({top:0,behavior:'instant'});}});
document.addEventListener('input',e=>{if(e.target.id!=='term-search')return;const value=e.target.value.trim().toLowerCase();const words=Object.keys(beginnerTerms).filter(w=>(w+' '+beginnerTerms[w]).toLowerCase().includes(value));$('term-results').innerHTML=words.length?glossaryHTML(words):'<p role="status">暂时没有这个词，试试中文名或缩写。</p>';});
render();
